import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n, h, v = map(int, line.split())

        # The cake is n x n with thickness 4.
        # Horizontal cut is at distance h from top, creating pieces of height h and n-h.
        # Vertical cut is at distance v from left, creating pieces of width v and n-v.
        # The four pieces have areas: h*v, h*(n-v), (n-h)*v, (n-h)*(n-v).
        # We need the maximum area multiplied by the thickness (4).

        heights = [h, n - h]
        widths = [v, n - v]

        max_area = 0
        for ht in heights:
            for wd in widths:
                area = ht * wd
                if area > max_area:
                    max_area = area

        volume = max_area * 4
        print(volume)
    except Exception:
        pass

if __name__ == "__main__":
    solve()
